xql_query:
// ============================================================
// Rule: WIN_PowerShell Password Input Window
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_PowerShell Password Input Window.
// Severity: SEV_040_HIGH
// Category: CREDENTIAL_ACCESS
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0002 - Execution
// Tactic: TA0006 - Credential Access
// Technique: T1056.002 - Input Capture: GUI Input Capture

// Fonte de dados: eventos do Cortex XDR
dataset = xdr_data  

// Filtro que seleciona apenas eventos do tipo USER_SESSION
// Esses eventos registram interações de janelas, sessões e atividades do usuário
| filter event_type = ENUM.USER_SESSION  

// Seleção dos campos relevantes para análise
| fields _time,                             // Data e hora do evento
         agent_hostname,                    // Nome do host onde ocorreu
         title as window_title,              // Título da janela ativa no momento
         event_sub_type,                    // Subtipo do evento (ex: WINDOW_FOCUS, SESSION_ACTIVE)
         actor_process_image_name,          // Nome do processo associado à sessão
         actor_process_command_line,        // Linha de comando do processo
         actor_effective_username,          // Usuário ativo na sessão
         causality_actor_process_command_line // Linha de comando do processo pai

// Filtro adicional para identificar janelas com título "Password Input"
// executadas por processos PowerShell, o que pode indicar captura de senha ou prompt falso
| filter window_title = "Password Input"
        and actor_process_image_name in ("powershell.exe", "pwsh.exe", "powershell_ise.exe")
